import{_ as a,c as e,a2 as r,o}from"./chunks/framework.CO0qOYmW.js";const p=JSON.parse('{"title":"模型网关概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/02-model-gateway/01-gateway/01-overview.md","filePath":"ai/02-model-gateway/01-gateway/01-overview.md","lastUpdated":1783608971000}'),d={name:"ai/02-model-gateway/01-gateway/01-overview.md"};function l(i,t,n,s,h,c){return o(),e("div",null,t[0]||(t[0]=[r('<h1 id="模型网关概述" tabindex="-1">模型网关概述 <a class="header-anchor" href="#模型网关概述" aria-label="Permalink to &quot;模型网关概述&quot;">​</a></h1><p>模型网关是企业 AI 应用的统一模型接入层，负责屏蔽不同模型供应商之间的接口差异，并提供路由、限流、审计、降级、缓存和成本统计等通用能力。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>统一入口</strong>：业务系统不直接依赖某个模型厂商，而是通过统一网关访问模型能力。</li><li><strong>稳定性保障</strong>：通过超时、重试、熔断、降级和多模型路由提升生产可用性。</li><li><strong>治理能力</strong>：集中管理密钥、模型准入、调用日志、Token 消耗和租户配额。</li></ul><h2 id="典型能力" tabindex="-1">典型能力 <a class="header-anchor" href="#典型能力" aria-label="Permalink to &quot;典型能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>多供应商接入</td><td>接入 OpenAI 兼容接口、Claude、国产模型和本地模型</td></tr><tr><td>推理封装</td><td>统一 Chat、Responses、流式输出、工具调用和结构化输出</td></tr><tr><td>路由策略</td><td>按任务类型、成本、延迟、稳定性选择合适模型</td></tr><tr><td>调用治理</td><td>管理限流、配额、审计、缓存、降级和异常追踪</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>理解模型网关的职责边界，避免在业务代码中直接散落模型调用逻辑。</li><li>掌握常见模型 API 的接入方式，形成统一请求和响应抽象。</li><li>建立企业级模型网关能力，包括路由、限流、审计、缓存和容灾。</li></ol>',8)]))}const u=a(d,[["render",l]]);export{p as __pageData,u as default};
